from fractions import Fraction as F
rows=[('A',13,(1,0,0,0)),('A',3,(0,0,0,1)),('B',9,(1,0,1,0)),('B',5,(0,0,1,1)),('C',5,(1,1,1,0)),('C',8,(0,0,1,0)),('D',6,(1,0,0,0)),('D',5,(0,0,1,1))]
tests='TUVW'; modes='ABCD'
loss=[[0,11,6,16],[22,0,20,8],[16,23,0,7],[18,11,20,0]]
cost=dict(zip(tests,map(F,['1.8','1.5','1.2','0.8'])))
def stop(ids):
 w=sum(rows[i][1] for i in ids)
 return min((F(sum(rows[i][1]*loss[a][modes.index(rows[i][0])] for i in ids),w),modes[a]) for a in range(4))
def value(ids,avail,budget):
 best,act=stop(ids)
 if budget:
  for t in avail:
   val=testval(ids,t,avail,budget)
   if val<best:best,act=val,t
 return best,act
def testval(ids,t,avail,budget):
 w=sum(rows[i][1] for i in ids); v=cost[t]
 for b in (0,1):
  sub=tuple(i for i in ids if rows[i][2][tests.index(t)]==b)
  if sub:v+=F(sum(rows[i][1] for i in sub),w)*value(sub,avail.replace(t,''),budget-1)[0]
 return v
ids=tuple(range(8))
fl={'STOP':float(stop(ids)[0])}
fl.update({t:float(testval(ids,t,tests,2)) for t in tests})
best,act=value(ids,tests,2)
nxt={}
if act in tests:
 for b in (0,1):
  sub=tuple(i for i in ids if rows[i][2][tests.index(act)]==b)
  nxt[str(b)]=value(sub,tests.replace(act,''),1)[1] if sub else 'IMPOSSIBLE'
print({'first':act,'first_losses':fl,'next':nxt})

