from fractions import Fraction as F
# W=1 selects the same persistent rows; repeated display adds no evidence.
rows=[('A',3,(0,0,0)),('B',5,(0,0,1)),('D',5,(0,0,1))]
modes='ABCD';tests='TUV'; costs=[F('1.8'),F('1.5'),F('7.2')]
loss=[[0,11,6,16],[22,0,20,8],[16,23,0,7],[18,11,20,0]]
def repairs(rs):
 w=sum(r[1] for r in rs)
 return {a:F(sum(r[1]*loss[j][modes.index(r[0])] for r in rs),w) for j,a in enumerate(modes)}
out=repairs(rows)
pol={}
for k,t in enumerate(tests):
 v=costs[k];pol[t]={}
 for b in [0,1]:
  sub=[r for r in rows if r[2][k]==b]
  if not sub:pol[t][str(b)]='IMPOSSIBLE';continue
  rr=repairs(sub);a=min(rr,key=rr.get);pol[t][str(b)]=a
  v+=F(sum(r[1] for r in sub),13)*rr[a]
 out[t]=v
a=min(out,key=out.get)
print({'posterior':{m:float(F(sum(r[1] for r in rows if r[0]==m),13)) for m in modes},'remaining_losses':{k:float(v) for k,v in out.items()},'action':a,'repair_after':pol.get(a,{})})

